import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { act } from 'react-dom/test-utils';
import ReactDOM from 'react-dom/client';
import React from 'react';
import { ThemeProvider } from '@gravity-ui/uikit';
import { App } from '../App';

(globalThis as any).IS_REACT_ACT_ENVIRONMENT = true;

let container: HTMLDivElement;
let root: ReactDOM.Root;

function mount(language: string) {
  Object.defineProperty(window.navigator, 'language', { value: language, configurable: true });
  container = document.createElement('div');
  document.body.appendChild(container);
  root = ReactDOM.createRoot(container);
  act(() => {
    root.render(
      <React.StrictMode>
        <ThemeProvider theme="light">
          <App />
        </ThemeProvider>
      </React.StrictMode>,
    );
  });
}

const text = () => container.textContent ?? '';
const radio = (label: string) =>
  [...container.querySelectorAll('label')].find((l) => l.textContent?.trim() === label) as HTMLElement;

beforeEach(() => localStorage.clear());
afterEach(() => {
  act(() => root.unmount());
  container.remove();
  document.documentElement.lang = '';
});

describe('language switcher', () => {
  it('defaults to English for an English browser', () => {
    mount('en-US');
    expect(text()).toContain('Welcome');
    expect(text()).toContain('Getting started');
    expect(document.documentElement.lang).toBe('en');
    expect(container.querySelector('[role="radiogroup"]')?.getAttribute('aria-label')).toBe('Language');
  });

  it('defaults to Russian for a Russian browser', () => {
    mount('ru-RU');
    expect(text()).toContain('Добро пожаловать');
    expect(document.documentElement.lang).toBe('ru');
  });

  it('switches language, updates html lang, and persists the choice', () => {
    mount('en-US');
    act(() => radio('Русский').click());
    expect(text()).toContain('Добро пожаловать');
    expect(text()).not.toContain('Welcome');
    expect(document.documentElement.lang).toBe('ru');
    expect(container.querySelector('[role="radiogroup"]')?.getAttribute('aria-label')).toBe('Язык');
    expect(localStorage.getItem('app-lang')).toBe('ru');

    act(() => radio('English').click());
    expect(text()).toContain('Welcome');
    expect(document.documentElement.lang).toBe('en');
    expect(localStorage.getItem('app-lang')).toBe('en');
  });

  it('restores the saved choice over the browser language', () => {
    localStorage.setItem('app-lang', 'en');
    mount('ru-RU');
    expect(text()).toContain('Welcome');
  });

  it('ignores an invalid saved value', () => {
    localStorage.setItem('app-lang', 'xx');
    mount('de-DE');
    expect(text()).toContain('Welcome');
  });

  it('marks the checked option', () => {
    mount('ru-RU');
    const checked = [...container.querySelectorAll('input[type="radio"]')].find(
      (i) => (i as HTMLInputElement).checked,
    ) as HTMLInputElement;
    expect(checked.value).toBe('ru');
  });
});
